custom_css:
/* ======================================================
   민음사 세계문학전집 희곡 스타일 · Embargo Area
   병동/지시.md 의 레이아웃 명세를 CSS 로 구현
   ====================================================== */

/* 본문 기본: 여백 넉넉 + 본명조 + 자간 약간 */
body {
    font-family: '본명조', 'Source Han Serif K', 'Noto Serif KR', 'Batang', serif;
    color: #1a1a1a;
    line-height: 1.85;
    letter-spacing: 0.015em;
    margin: 2em 2.4em;
    text-align: justify;
    word-break: keep-all;
}

/* 캐릭터 대사 — 내어쓰기(Hanging Indent): 이름 끝 지점에 맞춰 정렬 */
.dialogue, p.dialogue, .entry.dialogue {
    padding-left: 4.8em;
    text-indent: -4.8em;
    margin: 0.55em 0;
}

/* 캐릭터 이름 — 굵은 돋움(부크크 고딕), 콜론 없이 공백 구분 */
.dialogue .name, .name, .char-name, strong.name {
    font-family: '부크크 고딕', 'Bookk Gothic', 'Malgun Gothic', 'Noto Sans KR', sans-serif;
    font-weight: 700;
    letter-spacing: 0.04em;
    color: #111;
    margin-right: 0.6em;
}
/* 콜론 출력 제거 (엔진 기본 포맷이 콜론 포함해도 숨김 처리) */
.dialogue .name::after, .name::after { content: ""; }

/* 나레이션 / 지문 — 가벼운 톤 + 들여쓰기 */
.narration, p.narration, .entry.narration {
    color: #3a3a3a;
    text-indent: 1.5em;
    margin: 0.5em 0;
    font-style: normal;
}

/* 씬 전환 — 중앙 짧은 실선 */
hr, .scene-break, .scene-separator, hr.scene {
    width: 80px;
    height: 1px;
    border: 0;
    background: #999;
    margin: 2.5em auto;
    display: block;
}

/* 챕터 제목 — 제N장 형식, 고전적 소제목 */
h1, h1.chapter, .chapter-title {
    font-family: '부크크 고딕', 'Bookk Gothic', 'Malgun Gothic', sans-serif;
    font-weight: 700;
    font-size: 1.45em;
    text-align: center;
    letter-spacing: 0.14em;
    margin: 3.2em 0 2.2em;
    color: #0f0f0f;
}
h2, h2.scene, .scene-title {
    font-family: '부크크 고딕', sans-serif;
    font-weight: 600;
    font-size: 1.08em;
    text-align: center;
    letter-spacing: 0.08em;
    color: #2a2a2a;
    margin: 2.2em 0 1.4em;
}

/* 이펙트(기술명/콤보) 박스 — 세련된 상자 + 우측 정렬, 얇은 고딕, 넓은 자간 */
.effect, .effect-box, .effect-combo, blockquote.effect {
    background: #f6f3ec;
    border: 1px solid #d8d3c2;
    border-left: 2px solid #8a7e5c;
    border-radius: 2px;
    padding: 0.75em 1.25em;
    margin: 1.3em 1.8em;
    text-align: right;
    font-family: '부크크 고딕', 'Bookk Gothic', 'Malgun Gothic', sans-serif;
    font-weight: 300;
    font-size: 0.92em;
    letter-spacing: 0.14em;
    line-height: 1.65;
    color: #3f3a2e;
    box-shadow: 0 1px 0 rgba(0,0,0,0.03);
}
.effect .skill-name, .effect b, .effect strong {
    font-weight: 600;
    color: #1c1a14;
    letter-spacing: 0.18em;
}
/* 콤보 항목 간 구분 점 */
.effect .combo-sep::before { content: " · "; color: #a49c82; margin: 0 0.15em; }

/* 다이스 결과 — 〈 26 〉 기하학적 괄호, 현대적 숫자 폰트 */
.dice, .dice-result, .roll {
    font-family: '부크크 고딕', 'Bookk Gothic', 'Malgun Gothic', sans-serif;
    font-weight: 500;
    letter-spacing: 0.04em;
    color: #666;
    font-size: 0.92em;
}
.dice::before, .dice-result::before { content: "〈 "; color: #888; }
.dice::after,  .dice-result::after  { content: " 〉"; color: #888; }

/* 성공/CRITICAL 같은 상태 태그 — 작고 옅은 회색 */
.dice .status, .dice-status, .roll-status {
    font-size: 0.72em;
    color: #a0a0a0;
    margin-left: 0.5em;
    text-transform: uppercase;
    letter-spacing: 0.18em;
}

/* 스테이터스 바 (HP ―――|――――― 28/34) — 심플 라인 + 숫자 폰트 */
.status-bar, .char-status {
    font-family: '부크크 고딕', 'Bookk Gothic', 'Malgun Gothic', ui-monospace, monospace;
    letter-spacing: 0.06em;
    color: #4a4a4a;
    font-size: 0.9em;
}

/* 블록인용 — 성경 인용구, 깊은 독백 */
blockquote, .quote, .monologue {
    border-left: 2px solid #c9c2b3;
    margin: 1.6em 2.2em;
    padding: 0.4em 1.2em;
    color: #3a3a3a;
    font-family: '본명조', 'Source Han Serif K', serif;
    font-style: normal;
    font-size: 0.96em;
    line-height: 1.75;
}

/* 전투 불능 / 사망 — 취소선 + 공허한 여백 */
.death, .ko, .incapacitated {
    text-decoration: line-through;
    text-decoration-color: #999;
    color: #8a8a8a;
    margin: 2.8em 0;
}

/* 시스템/색상 코드 흔적 제거 (혹시 남을 경우 숨김) */
.system, .system-msg, .color-code, span[style*="color"] { color: inherit !important; }

/* 첫 문단 들여쓰기 없음(희곡 관례) */
.chapter + p, .scene-title + p, h1 + p, h2 + p { text-indent: 0; }

/* 표지 — 크림색 배경, 미니멀 타이포 */
.cover {
    background: #f4f1ea;
    color: #1a1a1a;
    text-align: center;
    padding: 6em 2em;
}
.cover .title {
    font-family: '부크크 고딕', sans-serif;
    font-weight: 700;
    font-size: 2.2em;
    letter-spacing: 0.16em;
    margin-bottom: 0.4em;
}
.cover .author {
    font-family: '본명조', serif;
    font-size: 1em;
    color: #555;
    letter-spacing: 0.08em;
}
